-- Read-only. The post-repair migration's report (supabase/migrations/20261019120000_hangtag_post_repair_integrity.sql):
-- run it any time to see whether the migration's changes are all in place — every row ok. After a run of schema.sql,
-- rows read false until the migration is run again. Generated by scripts/gen-post-repair.mjs.
SELECT check_name, ok FROM (
    SELECT 1 AS n, 'Returns take the bill line''s lock before the sum' AS check_name,
           COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_check_return_qty()')), '') LIKE '%pg_advisory_xact_lock(hashtextextended(''hangtag_return_line:''%' AS ok
    UNION ALL SELECT 2, 'Stock records of tracked products need their serial numbers or batch',
           EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.hangtag_stock_moves'::regclass AND t.tgname = 'hangtag_tracking_required' AND NOT t.tgisinternal)
    UNION ALL SELECT 3, 'Bills keep the unit sold',
           COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_save_sales(jsonb)')), '') LIKE '%kit, unit)%'
    UNION ALL SELECT 4, 'A deleted product leaves its mark, read only by its shop (and waits, like every shop table, when its plan has ended)',
           EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.hangtag_products'::regclass AND t.tgname = 'hangtag_product_deleted')
           AND EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.hangtag_deleted_products'::regclass AND t.tgname = 'zz_hangtag_subscription_guard')
           AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = 'public.hangtag_deleted_products'::regclass)
           AND NOT has_table_privilege('anon', 'public.hangtag_deleted_products', 'SELECT')
           AND NOT has_table_privilege('authenticated', 'public.hangtag_deleted_products', 'INSERT')
    UNION ALL SELECT 5, 'Capabilities answer an app account about its own shop only',
           COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_cap_on(uuid, text)')), '') LIKE '%p_owner IS DISTINCT FROM public.hangtag_shop_id() THEN RETURN FALSE%'
    UNION ALL SELECT 6, 'Billing notifications and exceptions: kept once each, in the database''s own billing mode, closed to app accounts',
           (to_regclass('public.hangtag_billing_settings') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_settings'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_settings', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_settings', 'SELECT,INSERT,UPDATE,DELETE'))
           AND (to_regclass('public.hangtag_billing_events') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_events'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_events', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_events', 'SELECT,INSERT,UPDATE,DELETE'))
           AND (to_regclass('public.hangtag_billing_exceptions') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_exceptions'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_exceptions', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_exceptions', 'SELECT,INSERT,UPDATE,DELETE'))
           AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'hangtag_billing_event_record') = 1
           AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'hangtag_billing_exception_open') = 1
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_billing_event_record(text, text, text, text, text, text, timestamptz, text, boolean)')), '') LIKE '%p_mode IS DISTINCT FROM bm%'
           AND NOT EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema = 'public' AND c.table_name = 'hangtag_billing_exceptions' AND c.column_name = 'owner_id')
           AND pg_get_constraintdef((SELECT k.oid FROM pg_constraint k WHERE k.conname = 'hangtag_billing_exceptions_kind_check')) LIKE '%mode_mismatch%'
           AND (SELECT s.billing_mode FROM public.hangtag_billing_settings s WHERE s.id) IN ('live', 'test')
    UNION ALL SELECT 7, 'Plan payments: none from a suspended shop; a halted AutoPay off first; a page only on an open payment; activation in the billing mode, never for refunded money; the provider asked a limited number of times per account',
           COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_subscription_checkout(text, text, text)')), '') LIKE '%s.owner_id = me AND s.suspended)%'
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_subscription_checkout(text, text, text)')), '') LIKE '%''cancel_mandate'', halted%'
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_subscription_attach(uuid, text, text)')), '') LIKE '%can''''t take a payment page any more%'
           AND (to_regprocedure('public.hangtag_subscription_activate_checked(uuid, text, numeric, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_subscription_activate_checked(uuid, text, numeric, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_subscription_activate_checked(uuid, text, numeric, text)'), 'EXECUTE'))
           AND (to_regclass('public.hangtag_billing_call_counts') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_call_counts'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_call_counts', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_call_counts', 'SELECT,INSERT,UPDATE,DELETE')) AND (to_regprocedure('public.hangtag_billing_call_claim(uuid, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_call_claim(uuid, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_call_claim(uuid, text)'), 'EXECUTE'))
    UNION ALL SELECT 8, 'Offers: a place is held only by a real checkout, one per shop',
           COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_promo_evaluate(uuid, text, text)')), '') LIKE '%count(DISTINCT y.owner_id)%provider_order_id IS NOT NULL%'
    UNION ALL SELECT 9, 'AutoPay set-ups registered; a charge recorded once, at the price agreed; a replaced set-up or an older report never moves a shop''s AutoPay',
           (to_regclass('public.hangtag_autopay_mandates') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_autopay_mandates'))
           AND NOT has_table_privilege('anon', 'public.hangtag_autopay_mandates', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_autopay_mandates', 'SELECT,INSERT,UPDATE,DELETE'))
           AND NOT EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema = 'public' AND c.table_name = 'hangtag_autopay_mandates' AND c.column_name = 'owner_id')
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_autopay_begin(boolean, text)')), '') LIKE '%hangtag_autopay_mandates%'
           AND (to_regprocedure('public.hangtag_autopay_attach_mandate(uuid, text, text, text, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_autopay_attach_mandate(uuid, text, text, text, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_autopay_attach_mandate(uuid, text, text, text, text)'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_autopay_report(text, text, text, text, numeric, text, timestamptz, timestamptz, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_autopay_report(text, text, text, text, numeric, text, timestamptz, timestamptz, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_autopay_report(text, text, text, text, numeric, text, timestamptz, timestamptz, text)'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_autopay_orphan(text, text, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_autopay_orphan(text, text, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_autopay_orphan(text, text, text)'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_autopay_check_claim(uuid)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_autopay_check_claim(uuid)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_autopay_check_claim(uuid)'), 'EXECUTE'))
           AND (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'hangtag_autopay_event') = 1
    UNION ALL SELECT 10, 'Reconciliation: one run at a time, its log, targets and checks, service role only',
           (to_regclass('public.hangtag_billing_reconcile_runs') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_reconcile_runs'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_reconcile_runs', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_reconcile_runs', 'SELECT,INSERT,UPDATE,DELETE'))
           AND (to_regclass('public.hangtag_billing_probes') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_probes'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_probes', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_probes', 'SELECT,INSERT,UPDATE,DELETE'))
           AND (to_regclass('public.hangtag_billing_payment_checks') IS NOT NULL AND (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.hangtag_billing_payment_checks'))
           AND NOT has_table_privilege('anon', 'public.hangtag_billing_payment_checks', 'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('authenticated', 'public.hangtag_billing_payment_checks', 'SELECT,INSERT,UPDATE,DELETE'))
           AND (to_regprocedure('public.hangtag_billing_reconcile_begin(int, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_reconcile_begin(int, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_reconcile_begin(int, text)'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_billing_reconcile_done(bigint, jsonb)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_reconcile_done(bigint, jsonb)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_reconcile_done(bigint, jsonb)'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_billing_known_payments(text, text[])') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_known_payments(text, text[])'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_known_payments(text, text[])'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_autopay_known(text, text[])') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_autopay_known(text, text[])'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_autopay_known(text, text[])'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_billing_probe_record(text, text, text, text)') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_probe_record(text, text, text, text)'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_probe_record(text, text, text, text)'), 'EXECUTE'))
           AND (to_regprocedure('public.hangtag_billing_integrity()') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_integrity()'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_integrity()'), 'EXECUTE'))
    UNION ALL SELECT 11, 'AutoPay offered, switched on and required of new trials only once its notifications are proven',
           (to_regprocedure('public.hangtag_billing_readiness()') IS NOT NULL AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_readiness()'), 'EXECUTE') AND NOT has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_readiness()'), 'EXECUTE'))
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_autopay_terms(uuid)')), '') LIKE '%hangtag_billing_readiness%'
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_platform_settings_save(jsonb)')), '') LIKE '%hangtag_billing_readiness%'
           AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_subscription_ensure(uuid)')), '') LIKE '%hangtag_billing_readiness%'
    UNION ALL SELECT 12, 'Billing review in the console: listed and settled by role, audited; the self-check by those who manage settings',
           (to_regprocedure('public.hangtag_billing_selfcheck_allowed()') IS NOT NULL AND has_function_privilege('authenticated', to_regprocedure('public.hangtag_billing_selfcheck_allowed()'), 'EXECUTE') AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_billing_selfcheck_allowed()'), 'EXECUTE')
               AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_billing_selfcheck_allowed()')), '') LIKE '%hangtag_platform_require(%')
           AND (to_regprocedure('public.hangtag_platform_billing_exceptions(text, int)') IS NOT NULL AND has_function_privilege('authenticated', to_regprocedure('public.hangtag_platform_billing_exceptions(text, int)'), 'EXECUTE') AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_platform_billing_exceptions(text, int)'), 'EXECUTE')
               AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_platform_billing_exceptions(text, int)')), '') LIKE '%hangtag_platform_require(%')
           AND (to_regprocedure('public.hangtag_platform_billing_exception_resolve(bigint, text)') IS NOT NULL AND has_function_privilege('authenticated', to_regprocedure('public.hangtag_platform_billing_exception_resolve(bigint, text)'), 'EXECUTE') AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_platform_billing_exception_resolve(bigint, text)'), 'EXECUTE')
               AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_platform_billing_exception_resolve(bigint, text)')), '') LIKE '%hangtag_platform_require(%')
           AND (to_regprocedure('public.hangtag_platform_billing_health()') IS NOT NULL AND has_function_privilege('authenticated', to_regprocedure('public.hangtag_platform_billing_health()'), 'EXECUTE') AND NOT has_function_privilege('anon', to_regprocedure('public.hangtag_platform_billing_health()'), 'EXECUTE')
               AND COALESCE((SELECT p.prosrc FROM pg_proc p WHERE p.oid = to_regprocedure('public.hangtag_platform_billing_health()')), '') LIKE '%hangtag_platform_require(%')
    UNION ALL SELECT 13, 'Every function added runs with its owner''s rights and an empty search path',
           (SELECT bool_and(p.prosecdef AND p.proconfig @> ARRAY['search_path=""']) FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.hangtag_billing_mode()'), to_regprocedure('public.hangtag_billing_event_seen(text, text, text)'), to_regprocedure('public.hangtag_billing_event_record(text, text, text, text, text, text, timestamptz, text, boolean)'), to_regprocedure('public.hangtag_billing_exception_open(text, text, text, uuid, uuid, numeric, jsonb, text)'), to_regprocedure('public.hangtag_subscription_activate_checked(uuid, text, numeric, text)'), to_regprocedure('public.hangtag_autopay_attach_mandate(uuid, text, text, text, text)'), to_regprocedure('public.hangtag_autopay_report(text, text, text, text, numeric, text, timestamptz, timestamptz, text)'), to_regprocedure('public.hangtag_autopay_orphan(text, text, text)'), to_regprocedure('public.hangtag_autopay_check_claim(uuid)'), to_regprocedure('public.hangtag_billing_reconcile_begin(int, text)'), to_regprocedure('public.hangtag_billing_reconcile_done(bigint, jsonb)'), to_regprocedure('public.hangtag_billing_known_payments(text, text[])'), to_regprocedure('public.hangtag_autopay_known(text, text[])'), to_regprocedure('public.hangtag_billing_probe_record(text, text, text, text)'), to_regprocedure('public.hangtag_billing_integrity()'), to_regprocedure('public.hangtag_billing_readiness()'), to_regprocedure('public.hangtag_billing_selfcheck_allowed()'), to_regprocedure('public.hangtag_platform_billing_exceptions(text, int)'), to_regprocedure('public.hangtag_platform_billing_exception_resolve(bigint, text)'), to_regprocedure('public.hangtag_platform_billing_health()'), to_regprocedure('public.hangtag_billing_call_claim(uuid, text)')))
           AND (SELECT count(*) FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.hangtag_billing_mode()'), to_regprocedure('public.hangtag_billing_event_seen(text, text, text)'), to_regprocedure('public.hangtag_billing_event_record(text, text, text, text, text, text, timestamptz, text, boolean)'), to_regprocedure('public.hangtag_billing_exception_open(text, text, text, uuid, uuid, numeric, jsonb, text)'), to_regprocedure('public.hangtag_subscription_activate_checked(uuid, text, numeric, text)'), to_regprocedure('public.hangtag_autopay_attach_mandate(uuid, text, text, text, text)'), to_regprocedure('public.hangtag_autopay_report(text, text, text, text, numeric, text, timestamptz, timestamptz, text)'), to_regprocedure('public.hangtag_autopay_orphan(text, text, text)'), to_regprocedure('public.hangtag_autopay_check_claim(uuid)'), to_regprocedure('public.hangtag_billing_reconcile_begin(int, text)'), to_regprocedure('public.hangtag_billing_reconcile_done(bigint, jsonb)'), to_regprocedure('public.hangtag_billing_known_payments(text, text[])'), to_regprocedure('public.hangtag_autopay_known(text, text[])'), to_regprocedure('public.hangtag_billing_probe_record(text, text, text, text)'), to_regprocedure('public.hangtag_billing_integrity()'), to_regprocedure('public.hangtag_billing_readiness()'), to_regprocedure('public.hangtag_billing_selfcheck_allowed()'), to_regprocedure('public.hangtag_platform_billing_exceptions(text, int)'), to_regprocedure('public.hangtag_platform_billing_exception_resolve(bigint, text)'), to_regprocedure('public.hangtag_platform_billing_health()'), to_regprocedure('public.hangtag_billing_call_claim(uuid, text)'))) = 21
) r ORDER BY n;
